{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/cta-actions.json
    The actions of a call to action: one or two links (ActionGroup), or an email field with a button (actions form).
    Props (p): id, actions, center. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_actions = ($p['actions'] ?? null)}
{var $v_center = ($p['center'] ?? false)}
{if og_t(og_eq(og_get($v_actions, ['mode']), 'form'))}
  {capture $c_4}
    {capture $c_1}
      {=og_text(og_get($v_actions, ['emailLabel']))}
    {/capture}
    {=og_include('compose/Label.latte', ['htmlFor' => og_s(og_tpl('{0}-email', [$v_id])), 'class' => 'sr-only', 'children' => (string) $c_1])|noescape}
    {capture $c_3}
      {=og_include('compose/Input.latte', ['type' => 'email', 'name' => 'email', 'class' => 'min-w-0 flex-1', 'attrs' => og_attrs(['id', og_tpl('{0}-email', [$v_id]), 'data-testid', 'field'])])|noescape}
      {capture $c_2}
        {=og_text(og_get($v_actions, ['cta']))}
      {/capture}
      {=og_include('compose/Button.latte', ['variant' => 'default', 'size' => 'default', 'type' => 'submit', 'attrs' => og_attrs(['data-testid', 'submit']), 'children' => (string) $c_2])|noescape}
    {/capture}
    {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'start', 'class' => 'w-full flex-wrap', 'children' => (string) $c_3])|noescape}
  {/capture}
  {=og_include('compose/Form.latte', ['method' => 'dialog', 'class' => og_s(og_cnv(['w-full max-w-md', (og_t($v_center) ? 'mx-auto' : '')])), 'attrs' => og_attrs(['data-testid', 'email-form']), 'children' => (string) $c_4])|noescape}
{else}
  {=og_include('blocks/action-group.latte', ['p' => ['primary' => og_get($v_actions, ['cta']), 'primaryHref' => og_get($v_actions, ['href']), 'secondary' => (og_t(og_eq(og_get($v_actions, ['mode']), 'two')) ? og_get($v_actions, ['secondary']) : null), 'secondaryHref' => og_get($v_actions, ['secondaryHref']), 'align' => (og_t($v_center) ? 'center' : 'start')]])|noescape}
{/if}
